  1→#!/usr/bin/perl
  2→
  3→use warnings;
  4→use strict;
  5→use autodie;
  6→my $slug = shift @ARGV; 
  7→my $url = shift @ARGV;
  8→
  9→if (!$url || $url !~ m|^https://www.youtube.com|) {
 10→	print STDERR "Usage:\n";
 11→	print STDERR "$0 project-name \"https://www.youtube.com/watch?v=jNQXAC9IVRw\"\n";
 12→	exit 1;
 13→}
 14→
 15→
 16→mkdir($slug);
 17→chdir($slug);
 18→my $video_file = `yt-dlp --console-title --restrict-filenames --write-auto-subs --write-subs "$url" --print filename --no-simulate`;
 19→chomp($video_file);
 20→my ($vtt) = glob('*.vtt');
 21→open(my $fh, "<", $vtt);
 22→my $this_start = 0;
 23→my $last_text_line = '';
 24→my @timestamps;
 25→my $out = "index.html";
 26→-d  'images' || mkdir('images');
 27→
 28→system("cp", "../styles.css", ".");
 29→
 30→open (my $outfile, ">", $out); 
 31→print $outfile <<EOF;
 32→<html>
 33→<head>
 34→ <link rel="stylesheet" type="text/css" href="styles.css" />
 35→ </head>
 36→<body>
 37→
 38→
 39→<h1>Youtube transcript</h1>
 40→Source: <a href="@{[$url]}" target="_blank">@{[$url]}</a>
 41→
 42→<ul>
 43→EOF
 44→
 45→
 46→my $timestamp_seen = 0;
 47→
 48→while (my $line = <$fh>) {
 49→	chomp $line;
 50→	if (!$timestamp_seen) {
 51→		if(  $line =~ /^\d\d:\d\d/ ) {
 52→				$timestamp_seen = 1;
 53→			} else {
 54→			next;
 55→		}
 56→	}
 57→
 58→
 59→		if ($line =~ /^\s*$/) { next}
 60→		if ($line =~ /<\/c>$/) { next }
 61→	if ($line =~ /(\d\d:\d\d:\d\d\.\d\d\d) --> (\d\d:\d\d:\d\d\.\d\d\d).*$/) {
 62→		$this_start = $1;
 63→		next;
 64→	}
 65→	if ($line eq $last_text_line) {
 66→		next;
 67→	}
 68→	push @timestamps, $this_start;
 69→	my $ts_filename = $this_start;
 70→	$ts_filename =~ s/:/-/g;
 71→	my $seconds;
 72→	if ($this_start =~ /^(\d+):(\d+):(\d+)/) {
 73→		my $hours = $1;
 74→		my $minutes = $2;
 75→		$seconds = $3;
 76→		$seconds += $minutes  *60;
 77→		$seconds += $hours * 3600;
 78→	}
 79→
 80→	print $outfile "<li>
 81→	<div class=\"grab\"><img src=\"images/$ts_filename.jpg\" /></div><div class=\"subtitle\"><span id=\"$this_start\">$line</span>
 82→<a href=\"@{[$url]}\&t=@{[$seconds]}\" target=\"blank\" class=\"videolink\">#</a>
 83→	</div></li>\n";
 84→	$last_text_line = $line;
 85→}
 86→
 87→print $outfile "
 88→</ul>
 89→</body>
 90→</html>";
 91→
 92→
 93→gen_images (@timestamps);
 94→
 95→sub gen_images {
 96→	my @timestamps = @_;	
 97→
 98→	foreach my $timestamp (@timestamps) {
 99→	my $ts_filename = $timestamp;
100→	$ts_filename =~ s/:/-/g;
101→		`ffmpeg -ss "$timestamp" -nostdin -i "$video_file"  -frames:v 1 -q:v "2" -vf scale=1024:-1  "images/$ts_filename.jpg"`;
102→	}
103→
104→}
